import { Inter, Noto_Sans_KR } from "next/font/google";

export const inter = Inter({
  weight: ["400", "500", "600", "700"],
  subsets: ["latin"],
  variable: "--font-inter",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the scroll target, normalized to 60fps. */
const OPEN_LERP = 0.14;

/**
 * Drives `--bloom-open` (0 → 1) on the referenced element based on how far
 * the viewport has scrolled through the element's own height — the pinned
 * "the bloom" section. As you scroll the pinned flower stays put while
 * `--bloom-open` rises from 0 (a closed bud, petals scaled to 0.42 and
 * rotated -8°) to 1 (fully open, petals at scale 1, rotation 0°). The
 * section's height in CSS is taller than the viewport on purpose (a sticky
 * inner), so the progress maps cleanly onto a few screens of scroll.
 *
 * The CSS fallback is `var(--bloom-open, 1)` — fully open — so without
 * JavaScript, and under reduced motion (where this hook does nothing), the
 * signature flower simply stands open. The lerp makes it scrubbable without
 * jitter: scrolling fast opens fast, scrolling slow opens slow, and
 * scrolling back up closes the flower again.
 *
 * The scroll handler is passive and only writes to a CSS custom property
 * (no layout work); the rAF loop runs only while the section is on screen
 * and the tab is visible.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;

    el.style.setProperty("--bloom-open", "0");

    let raf = 0;
    let running = false;
    let inView = true;
    let value = 0;
    let last = 0;
    let target = 0;

    const computeTarget = () => {
      const rect = el.getBoundingClientRect();
      // Progress is how far the section's top has traveled from "just
      // entered at the bottom" to "its content has scrolled past". We pin
      // via position: sticky in CSS, so the visible flower stays fixed
      // while this number climbs.
      const total = rect.height - window.innerHeight;
      if (total <= 0) {
        target = 1;
        return;
      }
      // When the section top is at or above the viewport top, progress
      // starts; it completes when the section's bottom reaches the fold.
      const traveled = Math.min(Math.max(-rect.top, 0), total);
      target = traveled / total;
    };

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const next = value + (target - value) * OPEN_LERP * (dt / 16.7);
      if (Math.abs(next - value) < 0.0002) return;
      value = next;
      el.style.setProperty("--bloom-open", value.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      computeTarget();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onScroll = () => {
      if (inView && !document.hidden) computeTarget();
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      document.removeEventListener("visibilitychange", onVisibility);
      // hand the element back to the CSS fallback (fully open)
      el.style.removeProperty("--bloom-open");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { inter, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useScrollProgress } from "./hooks/useScrollProgress";

const TITLE = "CHAPTER";

const CHAPTERS = [
  { no: "I", ko_title: "새벽", en_title: "Dawn", ko: "첫 장이 열린다. 잉크 냄새, 종이의 결, 창밖의 여명. 시간이 여기서 느려진다.", en: "The first page opens. Ink smell, paper grain, dawn beyond the window. Time slows here." },
  { no: "II", ko_title: "정오", en_title: "Noon", ko: "햇빛이 페이지 위에 떨어진다. 그림자가 글자 사이를 걷는다. 독자는 숨을 죽인다.", en: "Sunlight falls on the page. Shadows walk between letters. The reader holds their breath." },
  { no: "III", ko_title: "황혼", en_title: "Dusk", ko: "빛이 물러난다. 남은 것은 종이 위의 자국뿐. 읽는다는 것은 흔적을 따라가는 일이다.", en: "Light retreats. What remains are marks on paper. To read is to follow traces." },
];

/**
 * CHAPTER — 챕터, 시간의 책. Editorial-serif entry: a digital book where each
 * section is a chapter with drop caps and marginalia. scroll-scrub-pinned
 * (a pinned title page that resolves as you scroll), char-split-reveal
 * (drop-cap glyphs), clip-path-reveal (chapters wipe in).
 */
export default function ChapterPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const titleRef = useScrollProgress<HTMLDivElement>(reduced);

  useEffect(() => {
    rootRef.current?.classList.add("chapter-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "chapter" }, "*");
  }, []);

  return (
    <div ref={rootRef} className={`${inter.variable} ${notoSansKR.variable} chapter-root`}>
      <div ref={revealRef} className="chapter-doc">
        {/* scroll-scrub-pinned: the title page */}
        <section ref={titleRef} className="chapter-titlepage">
          <p className="chapter-kicker"><span lang="ko">시간의 책</span> · THE BOOK OF HOURS</p>
          <h1 className="chapter-title" aria-label="CHAPTER 챕터">
            {TITLE.split("").map((ch, i) => (
              <span key={i} aria-hidden="true" className="chapter-glyph" style={{ "--ch-i": i } as CSSProperties}>{ch}</span>
            ))}
          </h1>
          <p className="chapter-title__ko" lang="ko">챕터</p>
          <p className="chapter-titlepage__line"><span lang="ko">각 섹션이 챕터다.</span> Each section a chapter.</p>
        </section>

        {/* Chapters with drop-cap char-split + clip-path reveal */}
        <main className="chapter-body">
          {CHAPTERS.map((c) => (
            <article key={c.no} className="chapter-chap" data-reveal="">
              <div className="chapter-chap__head">
                <span className="chapter-chap__no">{c.no}</span>
                <h2 className="chapter-chap__title">
                  <span lang="ko">{c.ko_title}</span>
                  <em className="chapter-chap__en">{c.en_title}</em>
                </h2>
              </div>
              <p className="chapter-chap__text">
                <span className="chapter-dropcap" aria-hidden="true">{c.ko_title[0]}</span>
                <span lang="ko">{c.ko}</span>
              </p>
              <p className="chapter-chap__text chapter-chap__text--en">
                <em>{c.en}</em>
              </p>
              <aside className="chapter-marginalia" data-reveal="">
                <span lang="ko">여백의 메모 — 이 챕터는 천천히 읽어야 한다.</span>
              </aside>
            </article>
          ))}
        </main>

        <footer className="chapter-foot" data-reveal="">
          <p>© 2026 CHAPTER · <span lang="ko">시간의 책</span> · MIT</p>
          <p><span lang="ko">천천히 읽어라 — 시간은 기다린다.</span> read slowly — time waits.</p>
        </footer>
      </div>
    </div>
  );
}

/* CHAPTER 챕터 — the book of hours · editorial-serif
   aged paper / ink / drop-cap red · chapters with marginalia */

.chapter-root {
  --ch-bg: #fdf6e3;
  --ch-bg-warm: #f9f0d8;
  --ch-ink: #1a1a1a;
  --ch-ink-soft: #525252;
  --ch-red: #dc2626;
  --ch-rule: rgba(26,26,26,0.12);
  --ch-font: var(--font-inter), var(--font-noto-sans-kr), Georgia, serif;

  position: relative;
  min-height: 100vh;
  background: var(--ch-bg);
  color: var(--ch-ink);
  font-family: var(--ch-font);
  font-size: clamp(15px, 0.5vw + 13px, 18px);
  line-height: 1.8;
  overflow-x: hidden;
  overflow-x: clip;
}

.chapter-root :lang(ko) { font-family: var(--font-noto-sans-kr), serif; }
.chapter-root ::selection { background: var(--ch-red); color: var(--ch-bg); }
.chapter-root :focus-visible { outline: 2px solid var(--ch-red); outline-offset: 4px; }

.chapter-js [data-reveal] {
  opacity: 0; transform: translateY(20px);
  transition: opacity 1000ms cubic-bezier(0.16,1,0.3,1), transform 1000ms cubic-bezier(0.16,1,0.3,1);
}
.chapter-js [data-reveal].is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .chapter-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

.chapter-doc { position: relative; z-index: 1; max-width: 720px; margin: 0 auto; }

/* scroll-scrub-pinned: the title page */
.chapter-titlepage {
  position: sticky;
  top: 0;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 40px);
}
.chapter-kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.25em;
  color: var(--ch-red);
  margin: 0 0 30px;
}
.chapter-title {
  font-weight: 700;
  font-size: clamp(3rem, 12vw, 8rem);
  line-height: 0.9;
  margin: 0 0 12px;
  display: flex;
  gap: 0.03em;
}
.chapter-glyph {
  display: inline-block;
  opacity: 0;
  transform: translateY(40px) rotate(-5deg);
}
.chapter-js .chapter-glyph {
  animation: ch-glyph 900ms cubic-bezier(0.16,1,0.3,1) both;
  animation-delay: calc(var(--ch-i, 0) * 120ms + 300ms);
}
@keyframes ch-glyph { to { opacity: 1; transform: translateY(0) rotate(0); } }
@media (prefers-reduced-motion: reduce) {
  .chapter-glyph { opacity: 1; transform: none; animation: none; }
}
.chapter-title__ko {
  font-size: clamp(1rem, 2vw, 1.5rem);
  color: var(--ch-ink-soft);
  margin: 0 0 40px;
}
.chapter-titlepage__line {
  color: var(--ch-ink-soft);
  font-style: italic;
  margin: 0;
  font-size: clamp(0.9rem, 1.5vw, 1.05rem);
}

/* Chapters */
.chapter-body { padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 40px); }
.chapter-chap {
  margin-bottom: clamp(60px, 12vh, 120px);
  padding-top: 40px;
  border-top: 1px solid var(--ch-rule);
}
.chapter-chap:first-child { border-top: none; padding-top: 0; }
.chapter-chap__head {
  display: flex;
  align-items: baseline;
  gap: 20px;
  margin-bottom: 28px;
}
.chapter-chap__no {
  font-size: clamp(2.5rem, 6vw, 4rem);
  font-weight: 300;
  color: var(--ch-red);
  line-height: 1;
  font-style: italic;
}
.chapter-chap__title {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 700;
  margin: 0;
  line-height: 1.2;
}
.chapter-chap__en {
  display: block;
  font-size: 0.55em;
  font-style: italic;
  color: var(--ch-ink-soft);
  margin-top: 4px;
}
.chapter-chap__text {
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.9;
  margin: 0 0 16px;
  position: relative;
}
.chapter-chap__text--en {
  font-style: italic;
  color: var(--ch-ink-soft);
  font-size: 0.95rem;
}
.chapter-dropcap {
  float: left;
  font-size: 3.5em;
  line-height: 0.8;
  font-weight: 700;
  color: var(--ch-red);
  margin: 8px 12px 0 0;
  font-family: var(--font-noto-sans-kr), serif;
}
.chapter-marginalia {
  margin-top: 24px;
  padding: 12px 16px;
  border-left: 3px solid var(--ch-red);
  font-size: 0.85rem;
  font-style: italic;
  color: var(--ch-ink-soft);
  background: var(--ch-bg-warm);
}

/* Footer */
.chapter-foot {
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 40px);
  text-align: center;
  border-top: 1px solid var(--ch-rule);
  color: var(--ch-ink-soft);
  font-size: 0.82rem;
}
.chapter-foot p { margin: 0 0 6px; }
